<div class="page-heading"><div><span class="section-kicker">MEMBERSHIP NOMINATION #<?= (int)$row['id'] ?></span><h1><?= e($row['full_name']??$row['voter_name_snapshot']) ?></h1><p><?= e(label($row['status'])) ?> · Nominated by <?= e($row['nominated_by']) ?></p></div><a class="btn btn-light" href="<?= e(url('membership_nominations')) ?>">Back to nominations</a></div><section class="card card-body"><p>Voter ID: <?= e($row['voter_id']??'Record unavailable') ?></p><p>Current electoral location: <?= e(implode(' / ',array_filter([$row['current_constituency'],$row['current_branch'],$row['current_station']]))) ?></p><?php if($row['current_constituency_id']&&(int)$row['current_constituency_id']!==(int)$row['constituency_id_snapshot']): ?><p class="alert alert-warning">The constituency changed since nomination. Approval follows the current constituency.</p><?php endif; ?><p>Note: <?= nl2br(e(\App\Crypto::decrypt($row['note_encrypted'])?:'No note provided')) ?></p><?php if($row['decision_note_encrypted']): ?><p>Decision note: <?= nl2br(e(\App\Crypto::decrypt($row['decision_note_encrypted']))) ?></p><?php endif; ?><?php if($row['voter_record_id']): ?><a href="<?= e(url('voter',['id'=>$row['voter_record_id']])) ?>">View current voter details</a><?php endif; ?></section>
<?php if($row['status']==='pending'&&$canApprove): ?><section class="card card-body mt-4"><h2 class="h5">Review and decide</h2><p>Approval creates a membership immediately. Review the voter’s current details first. Jurisdiction is checked again when saving.</p><form method="post" action="<?= e(url()) ?>"><?= csrf() ?><input type="hidden" name="_action" value="membership_decide"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$row['revision'] ?>"><input type="hidden" name="voter_version" value="<?= e($row['voter_version']) ?>"><?= input('joined_on','Date joined',gmdate('Y-m-d'),'date',true,'max="'.gmdate('Y-m-d').'"') ?><?= select_field('status','Membership status',['active'=>'Active','inactive'=>'Inactive'],'active',true) ?><?= input('official_membership_id','Party ID (optional)','','text',false,'maxlength="64"') ?><label for="decision-note" class="form-label">Decision note (required for rejection)</label><textarea id="decision-note" name="decision_note" maxlength="1000" rows="3" class="form-control mb-3"></textarea><label class="d-block mb-3"><input type="checkbox" required> I have reviewed the current voter record and this decision.</label><button class="btn btn-primary" name="decision" value="approve">Approve and save membership</button> <button class="btn btn-outline-danger" name="decision" value="reject" formnovalidate>Reject nomination</button></form></section><?php elseif($row['status']==='pending'): ?><p class="alert alert-info mt-4">An administrator or another authorized constituency executive must decide this nomination.</p><?php endif; ?>
